<?php
namespace App\Console\Commands; use App\Services\Dapcode\AegisguardLoader; use App\Services\Dapcode\CodeMinifierService; use Illuminate\Console\Command; use Illuminate\Support\Str; class DapcodeAegisguardCommand extends Command { protected $signature = 'dapcode:aegisguard {action=status : Action: "status", "encrypt", or "decrypt"} {--force : Force operation without interactive confirmation}'; protected $aliases = ['aegisguard']; protected $description = 'Inspect, encrypt (.enc), or decrypt AegisGuard security protection files'; public function __construct() { parent::__construct(); $this->setAliases(['aegisguard']); } public function handle() { $action = strtolower(trim((string) $this->argument('action'))); if ($action === 'encrypt' || $action === 'enc') { return $this->call('dapcode:aegisguard-encrypt', [ '--force' => (bool) $this->option('force'), ]); } if ($action === 'decrypt' || $action === 'unenc' || $action === 'de') { return $this->call('dapcode:aegisguard-decrypt', [ '--force' => (bool) $this->option('force'), ]); } $this->info("======================================================="); $this->info("   DAPCODE AEGISGUARD — ENCRYPTION STATUS INSPECTOR     "); $this->info("======================================================="); $files = AegisguardLoader::getTargetAegisguardFiles(); $tableRows = []; $encryptedCount = 0; $plainCount = 0; $totalSize = 0; foreach ($files as $file) { $isEnc = AegisguardLoader::isFileEncrypted($file); $size = file_exists($file) ? filesize($file) : 0; $encSize = file_exists($file . '.enc') ? filesize($file . '.enc') : 0; $totalSize += ($size + $encSize); if ($isEnc) { $encryptedCount++; $statusLabel = '<info>🔒 ENCRYPTED (.enc)</info>'; } else { $plainCount++; $statusLabel = '<comment>📄 DECRYPTED / PLAIN</comment>'; } $relPath = str_replace('\\', '/', Str::after($file, base_path() . DIRECTORY_SEPARATOR)); $tableRows[] = [ 'file' => $relPath, 'status' => $statusLabel, 'php_size' => $this->formatBytes($size), 'enc_size' => $encSize > 0 ? $this->formatBytes($encSize) : '-', ]; } $this->table( ['File Kode AegisGuard', 'Status Enkripsi', 'Ukuran PHP', 'Ukuran .enc'], $tableRows ); $totalFiles = count($files); $this->info("======================================================="); $this->info(" [SUMMARY] Status Proteksi ({$totalFiles} file kode inti):"); $this->line(" 🔒 Terenkripsi (.enc) : <info>{$encryptedCount}</info> file (" . ($totalFiles > 0 ? round(($encryptedCount / $totalFiles) * 100, 1) : 0) . "%)"); $this->line(" 📄 Plain / Source     : <comment>{$plainCount}</comment> file (" . ($totalFiles > 0 ? round(($plainCount / $totalFiles) * 100, 1) : 0) . "%)"); $this->line(" 💾 Total Ukuran       : <info>" . $this->formatBytes($totalSize) . "</info>"); $this->newLine(); if ($encryptedCount < $totalFiles) { $this->line(" 💡 Jalankan <info>php artisan dapcode:aegisguard encrypt</info> untuk mengenkripsi seluruh kode ke .enc."); } if ($encryptedCount > 0) { $this->line(" 💡 Jalankan <info>php artisan dapcode:aegisguard decrypt</info> untuk memulihkan seluruh kode sumber."); } $this->info("======================================================="); return 0; } protected function formatBytes($bytes, $precision = 2) { if ($bytes <= 0) { return '0 B'; } $units = ['B', 'KB', 'MB', 'GB']; $base = log($bytes, 1024); $pow = floor($base); return round(pow(1024, $base - $pow), $precision) . ' ' . ($units[$pow] ?? 'B'); } }